import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  renameSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { readme } from "@smithable/adapter-tanstack";
import { readRecord } from "./generate.js";
import { ownRepository, uncommittedRefusal } from "./git.js";
import type { Io } from "./io.js";
import { loadSpec } from "./validate.js";

/** The one-line header of a generated file, in TypeScript (//) or CSS comment form. */
const GENERATED_HEADER =
  /^(?:\/\/ Generated by Smithable[^\n]*|\/\* Generated by Smithable[^\n]*\*\/)\n/;
// Whatever the kit's line starts with (a word, or a quoted name like "Ask").
const KIT_PREFIX = /^(\/\/|\/\*) Smithable app kit: (\S)/;

/**
 * `smithable detach`: turns the project into an ordinary one (ARCHITECTURE §6.8). Removes the
 * generated-file headers and Smithable's records, keeps the spec files as documentation in
 * docs/smithable/, and rewrites the README. Custom code is left as it is.
 */
export function detach(dir: string, io: Io): number {
  const recordPath = join(dir, ".smithable", "files.json");
  if (!existsSync(recordPath)) {
    io.err(`${dir} is not a Smithable project (there is no .smithable/files.json).\n`);
    return 1;
  }
  const refused =
    ownRepository(dir) &&
    uncommittedRefusal(dir, "so the detach can be reviewed and reverted on its own");
  if (refused) {
    io.err(refused);
    return 1;
  }
  const { ir, auth } = loadSpec(dir, io);
  if (!ir) return 1;

  const { files } = readRecord(dir);
  let cleaned = 0;
  for (const path of Object.keys(files)) {
    const file = join(dir, path);
    if (!existsSync(file)) continue;
    const text = readFileSync(file, "utf8");
    const plain = text
      .replace(GENERATED_HEADER, "")
      .replace(
        KIT_PREFIX,
        (_, comment: string, first: string) => `${comment} ${first.toUpperCase()}`,
      );
    if (plain !== text) {
      writeFileSync(file, plain);
      cleaned++;
    }
  }
  writeFileSync(join(dir, "README.md"), readme(ir, true, auth));

  const docs = join(dir, "docs", "smithable");
  const specs = readdirSync(dir).filter((f) => /^smithable(\.[a-z]+)?\.yml$/.test(f));
  mkdirSync(docs, { recursive: true });
  for (const spec of specs) renameSync(join(dir, spec), join(docs, spec));
  // Agent guidance about Smithable goes too; CLAUDE.md only if it is still just the pointer.
  const claude = join(dir, "CLAUDE.md");
  if (existsSync(claude) && readFileSync(claude, "utf8").trim() === "@AGENTS.md") rmSync(claude);
  for (const path of [
    "smithable.lock",
    ".smithable",
    join("data", ".smithable"),
    "AGENTS.md",
    ".mcp.json",
  ]) {
    rmSync(join(dir, path), { recursive: true, force: true });
  }
  io.out(
    `Detached: ${cleaned} files no longer mention Smithable, the README is rewritten, and ${specs.join(", ")} ` +
      `moved to docs/smithable/ as documentation.\nThis is now an ordinary TanStack Start + Drizzle project.\n` +
      // One change, not committed (ARCHITECTURE §6.8): the person looks at it, then keeps it or not.
      "Review the change with git diff, then commit it; or take it back with git checkout . && git clean -fd.\n",
  );
  return 0;
}
